72	export const COMPONENTS_ROOT_DIR = 'Hazard_Trigger_Data/Components';
73	
74	function cleanPath(p: string): string {
75	  return normalizePath(p).replace(/\\/g, '/');
76	}
77	
78	export class ComponentScanner {
79	  /**
80	   * Scans all subfolders and JSON files under Hazard_Trigger_Data/Components/
81	   * Enriches folders and files with metadata from _components_meta.json
82	   */
83	  public static async scanAll(app: App): Promise<ComponentFolderNode[]> {
84	    const adapter = app.vault.adapter;
85	    const rootPath = cleanPath(COMPONENTS_ROOT_DIR);
86	    const rootExists = await adapter.exists(rootPath);
87	
88	    if (!rootExists) {
89	      try {
90	        await adapter.mkdir(rootPath);
91	      } catch (e) {
92	        console.warn('[ComponentScanner] Root creation note:', e);
93	      }
94	      return [];
95	    }
96	
97	    // 1. Load Metadata Registry if available
98	    let registry: ComponentsMetaRegistry = { folders: {}, files: {} };
99	    const primaryMetaPath = cleanPath(`${COMPONENTS_ROOT_DIR}/_components_meta.json`);
100	    const fallbackMetaPath = cleanPath(`${COMPONENTS_ROOT_DIR}/_meta.json`);
101	
102	    try {
103	      if (await adapter.exists(primaryMetaPath)) {
104	        const raw = await adapter.read(primaryMetaPath);
105	        registry = JSON.parse(raw);
106	      } else if (await adapter.exists(fallbackMetaPath)) {
107	        const raw = await adapter.read(fallbackMetaPath);
108	        registry = JSON.parse(raw);
109	      }
110	    } catch (err) {
111	      console.warn('[ComponentScanner] Metadata registry parse warning:', err);
112	    }
113	
114	    const listed = await adapter.list(rootPath);
115	    const folders: ComponentFolderNode[] = [];
116	
117	    // Sort folders by path initially
118	    const sortedFolderPaths = [...listed.folders].map(cleanPath).sort();
119	
120	    for (const folderPath of sortedFolderPaths) {
121	      const folderName = folderPath.split('/').pop() || folderPath;
122	      const relFolderPath = folderPath.startsWith(rootPath + '/')
123	        ? folderPath.slice(rootPath.length + 1)
124	        : folderName;
125	
126	      const folderMeta = registry.folders?.[relFolderPath] || registry.folders?.[folderName];
127	
128	      const folderContents = await adapter.list(folderPath);
129	      const files: ComponentFileNode[] = [];
130	
131	      // Sort files in folder, filtering out system/metadata files starting with "_"
132	      const sortedFilePaths = [...folderContents.files]
133	        .map(cleanPath)
134	        .filter((f) => {
135	          const base = f.split('/').pop() || f;
136	          return f.endsWith('.json') && !base.startsWith('_');
137	        })
138	        .sort();
139	
140	      for (const filePath of sortedFilePaths) {
141	        const fileName = filePath.split('/').pop() || filePath;
142	        const relFilePath = filePath.startsWith(rootPath + '/')
143	          ? filePath.slice(rootPath.length + 1)
144	          : `${relFolderPath}/${fileName}`;
145	
146	        try {
147	          const raw = await adapter.read(filePath);
148	          const parsed: Record<string, ComponentEntry> = JSON.parse(raw);
149	
150	          // Find file metadata with resilient key matching
151	          const fileMeta =
152	            registry.files?.[relFilePath] ||
153	            registry.files?.[fileName] ||
154	            registry.files?.[relFilePath.replace(/\.json$/i, '')] ||
155	            registry.files?.[fileName.replace(/\.json$/i, '')];
156	
157	          // Format clean fallback display name (e.g. "1_subjects.json" -> "Subjects")
158	          const fallbackCleanName = fileName
159	            .replace(/\.json$/i, '')
160	            .replace(/^[_0-9]+/, '')
161	            .replace(/[-_]/g, ' ')
162	            .trim();
163	
164	          const displayName =
165	            fileMeta?.displayName ||
166	            (fallbackCleanName.charAt(0).toUpperCase() + fallbackCleanName.slice(1) || fileName);
167	
168	          files.push({
169	            fileName,
170	            displayName,
171	            relPath: relFilePath,
172	            meta: fileMeta,
173	            entries: parsed,
174	          });
175	        } catch (err) {
176	          console.error(`[ComponentScanner] Failed to parse ${filePath}:`, err);
177	        }
178	      }
179	
180	      // Sort files by meta.order, then natural alphanumeric
181	      files.sort((a, b) => {
182	        const orderA = typeof a.meta?.order === 'number' ? a.meta.order : 9999;
183	        const orderB = typeof b.meta?.order === 'number' ? b.meta.order : 9999;
184	        if (orderA !== orderB) return orderA - orderB;
185	        return a.fileName.localeCompare(b.fileName, undefined, { numeric: true });
186	      });
187	
188	      const fallbackFolderClean = folderName
189	        .replace(/^[_0-9]+/, '')
190	        .replace(/[-_]/g, ' ')
191	        .trim();
192	
193	      const folderDisplayName =
194	        folderMeta?.displayName ||
195	        (fallbackFolderClean.charAt(0).toUpperCase() + fallbackFolderClean.slice(1) || folderName);
196	
197	      folders.push({
198	        folderName,
199	        displayName: folderDisplayName,
200	        relPath: relFolderPath,
201	        meta: folderMeta,
202	        files,
203	      });
204	    }
205	
206	    // Sort folders by meta.order, then natural alphanumeric
207	    folders.sort((a, b) => {
208	      const orderA = typeof a.meta?.order === 'number' ? a.meta.order : 9999;
209	      const orderB = typeof b.meta?.order === 'number' ? b.meta.order : 9999;
210	      if (orderA !== orderB) return orderA - orderB;
211	      return a.folderName.localeCompare(b.folderName, undefined, { numeric: true });
212	    });
213	
214	    return folders;
215	  }
216	}
