4	export const CONDITIONS_DIR = 'Hazard_Trigger_Data/Conditions';
5	export const CONDITIONS_FILE_PATH = 'Hazard_Trigger_Data/Conditions/conditions.json';
6	
7	function cleanPath(p: string): string {
8	  return normalizePath(p).replace(/\\/g, '/');
9	}
10	
11	export class ConditionManager {
12	  /**
13	   * Sanitizes a ConditionEntry to strictly conform to the clean V2 schema.
14	   */
15	  public static sanitizeCondition(raw: any): ConditionEntry {
16	    const clean: ConditionEntry = {
17	      display_name: raw.display_name || 'Unnamed Condition',
18	      category: raw.category || 'General',
19	      description: raw.description || '',
20	    };
21	
22	    if (raw.completed === true) {
23	      clean.completed = true;
24	    }
25	
26	    if (Array.isArray(raw.tag_team) && raw.tag_team.length > 0) {
27	      clean.tag_team = raw.tag_team.filter(Boolean);
28	    }
29	
30	    if (Array.isArray(raw.conflicts_with) && raw.conflicts_with.length > 0) {
31	      clean.conflicts_with = raw.conflicts_with.filter(Boolean);
32	    }
33	
34	    return clean;
35	  }
36	
37	  /**
38	   * Ensures the Conditions folder and primary conditions.json exist in the vault.
39	   */
40	  public static async ensureConditionsFolder(app: App): Promise<void> {
41	    const adapter = app.vault.adapter;
42	    const folderPath = cleanPath(CONDITIONS_DIR);
43	
44	    if (!(await adapter.exists(folderPath))) {
45	      try {
46	        await adapter.mkdir(folderPath);
47	      } catch (e) {
48	        console.warn('[ConditionManager] Folder creation notice:', e);
49	      }
50	    }
51	
52	    const filePath = cleanPath(CONDITIONS_FILE_PATH);
53	    if (!(await adapter.exists(filePath))) {
54	      try {
55	        await adapter.write(filePath, JSON.stringify({}, null, 2));
56	      } catch (e) {
57	        console.warn('[ConditionManager] File creation notice:', e);
58	      }
59	    }
60	  }
61	
62	  /**
63	   * Loads all conditions from Hazard_Trigger_Data/Conditions/.
64	   * Scans all JSON files inside the folder and merges their dictionaries.
65	   */
66	  public static async loadAllConditions(app: App): Promise<Record<string, ConditionEntry>> {
67	    await this.ensureConditionsFolder(app);
68	    const adapter = app.vault.adapter;
69	    const folderPath = cleanPath(CONDITIONS_DIR);
70	    const conditionsMap: Record<string, ConditionEntry> = {};
71	
72	    try {
73	      const listed = await adapter.list(folderPath);
74	      const jsonFiles = listed.files.filter((f) => f.endsWith('.json'));
75	
76	      for (const filePath of jsonFiles) {
77	        try {
78	          const raw = await adapter.read(cleanPath(filePath));
79	          const parsed = JSON.parse(raw);
80	          if (parsed && typeof parsed === 'object') {
81	            Object.entries(parsed).forEach(([key, val]) => {
82	              conditionsMap[key] = this.sanitizeCondition(val);
83	            });
84	          }
85	        } catch (err) {
86	          console.error(`[ConditionManager] Failed to parse condition file ${filePath}:`, err);
87	        }
88	      }
89	    } catch (e) {
90	      console.warn('[ConditionManager] Error loading conditions:', e);
91	    }
92	
93	    return conditionsMap;
94	  }
95	
96	  /**
97	   * Writes the entire conditions dictionary back to Hazard_Trigger_Data/Conditions/conditions.json.
98	   */
99	  public static async saveAllConditions(
100	    app: App,
101	    conditions: Record<string, ConditionEntry>,
102	    targetFileName: string = 'conditions.json'
103	  ): Promise<boolean> {
104	    await this.ensureConditionsFolder(app);
105	    const adapter = app.vault.adapter;
106	    const filePath = cleanPath(`${CONDITIONS_DIR}/${targetFileName}`);
107	
108	    try {
109	      const sanitized: Record<string, ConditionEntry> = {};
110	      Object.entries(conditions).forEach(([k, v]) => {
111	        sanitized[k] = this.sanitizeCondition(v);
112	      });
113	
114	      await adapter.write(filePath, JSON.stringify(sanitized, null, 2));
115	      return true;
116	    } catch (err) {
117	      console.error(`[ConditionManager] Failed to write conditions to ${filePath}:`, err);
118	      return false;
119	    }
120	  }
121	
122	  /**
123	   * Saves or updates a single condition entry.
124	   */
125	  public static async saveCondition(
126	    app: App,
127	    id: string,
128	    entry: ConditionEntry
129	  ): Promise<boolean> {
130	    const all = await this.loadAllConditions(app);
131	    all[id] = this.sanitizeCondition(entry);
132	    return await this.saveAllConditions(app, all);
133	  }
134	
135	  /**
136	   * Deletes a condition entry by Hex ID.
137	   */
138	  public static async deleteCondition(app: App, id: string): Promise<boolean> {
139	    const all = await this.loadAllConditions(app);
140	    if (all[id]) {
141	      delete all[id];
142	      return await this.saveAllConditions(app, all);
143	    }
144	    return false;
145	  }
146	}
