1	import { App, normalizePath } from 'obsidian';
2	import { ComponentEntry, ComponentFileNode } from './componentScanner';
3	import { MatrixDomainNode, MatrixStateDefinition } from '../types/schema';
4	
5	export const MATRICES_ROOT_DIR = 'Hazard_Trigger_Data/Matrices';
6	
7	function cleanPath(p: string): string {
8	  return normalizePath(p).replace(/\\/g, '/');
9	}
10	
11	export class MatrixScanner {
12	  /**
13	   * Dynamically scans all Matrix Domain subdirectories in Hazard_Trigger_Data/Matrices/.
14	   * Parses _matrix.json and all child component files dynamically with zero hardcoding.
15	   */
16	  public static async scanAll(app: App): Promise<MatrixDomainNode[]> {
17	    const adapter = app.vault.adapter;
18	    const rootPath = cleanPath(MATRICES_ROOT_DIR);
19	    const rootExists = await adapter.exists(rootPath);
20	
21	    if (!rootExists) {
22	      try {
23	        await adapter.mkdir(rootPath);
24	      } catch (e) {
25	        console.warn('[MatrixScanner] Root creation note:', e);
26	      }
27	      return [];
28	    }
29	
30	    const listed = await adapter.list(rootPath);
31	    const matrixDomains: MatrixDomainNode[] = [];
32	
33	    const sortedFolderPaths = [...listed.folders].map(cleanPath).sort();
34	
35	    for (const folderPath of sortedFolderPaths) {
36	      const folderName = folderPath.split('/').pop() || folderPath;
37	      const relFolderPath = folderPath.startsWith(rootPath + '/')
38	        ? folderPath.slice(rootPath.length + 1)
39	        : folderName;
40	
41	      const folderContents = await adapter.list(folderPath);
42	
43	      // 1. Read _matrix.json for dynamic Matrix States definition
44	      let states: MatrixStateDefinition[] = [];
45	      const matrixDefPath = cleanPath(`${folderPath}/_matrix.json`);
46	
47	      try {
48	        if (await adapter.exists(matrixDefPath)) {
49	          const raw = await adapter.read(matrixDefPath);
50	          const parsed = JSON.parse(raw);
51	          if (Array.isArray(parsed)) {
52	            states = parsed as MatrixStateDefinition[];
53	          }
54	        }
55	      } catch (err) {
56	        console.error(`[MatrixScanner] Failed to parse _matrix.json in ${folderPath}:`, err);
57	      }
58	
59	      // 2. Read all child component files
60	      const files: ComponentFileNode[] = [];
61	      const sortedFilePaths = [...folderContents.files]
62	        .map(cleanPath)
63	        .filter((f) => {
64	          const base = f.split('/').pop() || f;
65	          return f.endsWith('.json') && !base.startsWith('_');
66	        })
67	        .sort();
68	
69	      for (const filePath of sortedFilePaths) {
70	        const fileName = filePath.split('/').pop() || filePath;
71	        const relFilePath = `Matrices/${relFolderPath}/${fileName}`;
72	
73	        try {
74	          const raw = await adapter.read(filePath);
75	          const parsed: Record<string, ComponentEntry> = JSON.parse(raw);
76	
77	          const fallbackCleanName = fileName
78	            .replace(/\.json$/i, '')
79	            .replace(/^[_0-9]+/, '')
80	            .replace(/[-_]/g, ' ')
81	            .trim();
82	
83	          const displayName =
84	            fallbackCleanName.charAt(0).toUpperCase() + fallbackCleanName.slice(1) || fileName;
85	
86	          files.push({
87	            fileName,
88	            displayName,
89	            relPath: relFilePath,
90	            entries: parsed,
91	          });
92	        } catch (err) {
93	          console.error(`[MatrixScanner] Failed to parse ${filePath}:`, err);
94	        }
95	      }
96	
97	      const fallbackFolderClean = folderName
98	        .replace(/^[_0-9]+/, '')
99	        .replace(/[-_]/g, ' ')
100	        .trim();
101	
102	      const folderDisplayName =
103	        fallbackFolderClean.charAt(0).toUpperCase() + fallbackFolderClean.slice(1) || folderName;
104	
105	      matrixDomains.push({
106	        domainId: folderName,
107	        displayName: folderDisplayName,
108	        relPath: `Matrices/${relFolderPath}`,
109	        states,
110	        files,
111	      });
112	    }
113	
114	    return matrixDomains;
115	  }
116	}
