139	  /**
140	   * Lists all templates saved in Hazard_Trigger_Data/Templates/.
141	   */
142	  public static async listTemplates(app: App): Promise<HazardTemplate[]> {
143	    await this.ensureFolders(app);
144	    const adapter = app.vault.adapter;
145	    const templatesFolder = cleanPath(TEMPLATES_FOLDER_PATH);
146	    const jsonPaths = await this.collectJsonFiles(app, templatesFolder);
147	    const templates: HazardTemplate[] = [];
148	
149	    for (const filePath of jsonPaths) {
150	      try {
151	        const raw = await adapter.read(filePath);
152	        const parsed = JSON.parse(raw);
153	        const fileName = filePath.split('/').pop() || filePath;
154	        const fallbackName = fileName.replace(/\.json$/i, '').replace(/[-_]/g, ' ');
155	
156	        // If it conforms to HazardTemplate schema
157	        if (parsed && typeof parsed === 'object') {
158	          if (parsed.selections && typeof parsed.selections === 'object') {
159	            templates.push({
160	              id: parsed.id || `template_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
161	              name: parsed.name || fallbackName,
162	              description: parsed.description || '',
163	              category: parsed.category || 'General',
164	              tags: Array.isArray(parsed.tags) ? parsed.tags : [],
165	              createdAt: parsed.createdAt || Date.now(),
166	              updatedAt: parsed.updatedAt || Date.now(),
167	              selections: parsed.selections,
168	              randomPools: parsed.randomPools || {},
169	              baseEmotionStates: Array.isArray(parsed.baseEmotionStates)
170	                ? parsed.baseEmotionStates
171	                : parsed.baseEmotionState
172	                ? [parsed.baseEmotionState]
173	                : [],
174	              unlockedEmotionPools: Array.isArray(parsed.unlockedEmotionPools)
175	                ? parsed.unlockedEmotionPools
176	                : Array.isArray(parsed.activeEmotionStates)
177	                ? parsed.activeEmotionStates
178	                : [],
179	              basePoseStates: Array.isArray(parsed.basePoseStates) ? parsed.basePoseStates : [],
180	              unlockedPosePools: Array.isArray(parsed.unlockedPosePools) ? parsed.unlockedPosePools : [],
181	              unlockLockedAll: Boolean(parsed.unlockLockedAll),
182	              unlockKeys: Array.isArray(parsed.unlockKeys) ? parsed.unlockKeys : [],
183	              unlockedOptionKeys: Array.isArray(parsed.unlockedOptionKeys) ? parsed.unlockedOptionKeys : [],
184	              lock: parsed.lock || parsed.locked_options || parsed.lockedRandomSelections || {},
185	              locked_options: parsed.locked_options || parsed.lock || parsed.lockedRandomSelections || {},
186	              lockedRandomSelections: parsed.lockedRandomSelections || parsed.lock || parsed.locked_options || {},
187	              filePath,
188	            });
189	          } else {
190	            // Check if it's a legacy or custom JSON template
191	            templates.push({
192	              id: parsed.id || fileName.replace(/\.json$/i, ''),
193	              name: parsed.name || fallbackName,
194	              description: parsed.description || parsed.notes || '',
195	              category: parsed.category || 'Legacy',
196	              tags: Array.isArray(parsed.tags) ? parsed.tags : [],
197	              createdAt: Date.now(),
198	              updatedAt: Date.now(),
199	              selections: parsed.selections || {},
200	              randomPools: parsed.randomPools || {},
201	              baseEmotionStates: [],
202	              unlockedEmotionPools: [],
203	              basePoseStates: [],
204	              unlockedPosePools: [],
205	              unlockLockedAll: false,
206	              unlockKeys: [],
207	              unlockedOptionKeys: [],
208	              lockedRandomSelections: {},
209	              filePath,
210	            });
211	          }
212	        }
213	      } catch (err) {
214	        console.error(`[TemplateManager] Failed to parse template at ${filePath}:`, err);
215	      }
216	    }
217	
218	    // Sort templates by updated timestamp descending, then name ascending
219	    templates.sort((a, b) => {
220	      if (b.updatedAt !== a.updatedAt) return b.updatedAt - a.updatedAt;
221	      return a.name.localeCompare(b.name);
222	    });
223	
224	    return templates;
225	  }
