227	  /**
228	   * Saves or updates a template in Hazard_Trigger_Data/Templates/.
229	   */
230	  public static async saveTemplate(app: App, template: HazardTemplate): Promise<HazardTemplate> {
231	    await this.ensureFolders(app);
232	    const adapter = app.vault.adapter;
233	
234	    let targetFilePath = template.filePath;
235	    if (!targetFilePath) {
236	      const sanitizedName = template.name
237	        .trim()
238	        .replace(/[/\\?%*:|"<>]/g, '_')
239	        .replace(/\s+/g, '_');
240	      targetFilePath = cleanPath(`${TEMPLATES_FOLDER_PATH}/${sanitizedName}.json`);
241	    }
242	
243	    const updatedTemplate: HazardTemplate = {
244	      ...template,
245	      updatedAt: Date.now(),
246	      filePath: targetFilePath,
247	    };
248	
249	    const serialized = JSON.stringify(
250	      {
251	        id: updatedTemplate.id,
252	        name: updatedTemplate.name,
253	        description: updatedTemplate.description,
254	        category: updatedTemplate.category,
255	        tags: updatedTemplate.tags,
256	        createdAt: updatedTemplate.createdAt,
257	        updatedAt: updatedTemplate.updatedAt,
258	        selections: updatedTemplate.selections,
259	        randomPools: updatedTemplate.randomPools || {},
260	        baseEmotionStates: updatedTemplate.baseEmotionStates || [],
261	        unlockedEmotionPools: updatedTemplate.unlockedEmotionPools || [],
262	        basePoseStates: updatedTemplate.basePoseStates || [],
263	        unlockedPosePools: updatedTemplate.unlockedPosePools || [],
264	        unlockLockedAll: Boolean(updatedTemplate.unlockLockedAll),
265	        unlockKeys: updatedTemplate.unlockKeys || [],
266	        unlockedOptionKeys: updatedTemplate.unlockedOptionKeys || [],
267	        lock: updatedTemplate.lock || updatedTemplate.locked_options || updatedTemplate.lockedRandomSelections || {},
268	        locked_options: updatedTemplate.locked_options || updatedTemplate.lock || updatedTemplate.lockedRandomSelections || {},
269	        lockedRandomSelections: updatedTemplate.lockedRandomSelections || updatedTemplate.lock || updatedTemplate.locked_options || {},
270	      },
271	      null,
272	      2
273	    );
274	
275	    await adapter.write(targetFilePath, serialized);
276	    return updatedTemplate;
277	  }
