1	import React, { useState, useRef, useEffect, useMemo } from 'react';
2	import { Plus, Check, ChevronDown, Sparkles, Search, Tag } from 'lucide-react';
3	
4	interface NotionCategorySelectProps {
5	  value: string;
6	  allCategories: string[];
7	  onChange: (newCategory: string) => void;
8	  onAddNewCategory?: (createdCategory: string) => void;
9	}
10	
11	export function getCategoryBadgeStyle(category: string): string {
12	  const cat = (category || 'General').toLowerCase().trim();
13	  if (cat.includes('subject')) return 'bg-amber-500/20 text-amber-300 border-amber-400/50';
14	  if (cat.includes('pose') || cat.includes('action')) return 'bg-cyan-500/20 text-cyan-300 border-cyan-400/50';
15	  if (cat.includes('apparel') || cat.includes('clothing') || cat.includes('outfit')) return 'bg-purple-500/20 text-purple-300 border-purple-400/50';
16	  if (cat.includes('environment') || cat.includes('background') || cat.includes('setting')) return 'bg-emerald-500/20 text-emerald-300 border-emerald-400/50';
17	  if (cat.includes('camera') || cat.includes('framing') || cat.includes('angle')) return 'bg-sky-500/20 text-sky-300 border-sky-400/50';
18	  if (cat.includes('expression') || cat.includes('mood') || cat.includes('emotion')) return 'bg-pink-500/20 text-pink-300 border-pink-400/50';
19	  if (cat.includes('lighting') || cat.includes('atmosphere')) return 'bg-yellow-500/20 text-yellow-300 border-yellow-400/50';
20	  if (cat.includes('style') || cat.includes('art') || cat.includes('quality')) return 'bg-fuchsia-500/20 text-fuchsia-300 border-fuchsia-400/50';
21	  return 'bg-indigo-500/20 text-indigo-300 border-indigo-400/50';
22	}
23	
24	export const NotionCategorySelect: React.FC<NotionCategorySelectProps> = ({
25	  value,
26	  allCategories,
27	  onChange,
28	  onAddNewCategory,
29	}) => {
30	  const [isOpen, setIsOpen] = useState(false);
31	  const [search, setSearch] = useState('');
32	  const popoverRef = useRef<HTMLDivElement>(null);
33	  const searchInputRef = useRef<HTMLInputElement>(null);
34	
35	  // Close on outside click
36	  useEffect(() => {
37	    const handleClickOutside = (e: MouseEvent) => {
38	      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
39	        setIsOpen(false);
40	        setSearch('');
41	      }
42	    };
43	    if (isOpen) {
44	      document.addEventListener('mousedown', handleClickOutside);
45	      setTimeout(() => searchInputRef.current?.focus(), 50);
46	    }
47	    return () => document.removeEventListener('mousedown', handleClickOutside);
48	  }, [isOpen]);
49	
50	  // Clean category options
51	  const cleanCategories = useMemo(() => {
52	    const list = allCategories.filter((c) => c && c.toLowerCase() !== 'all');
53	    return Array.from(new Set(list));
54	  }, [allCategories]);
55	
56	  // Filtered categories
57	  const filteredCategories = useMemo(() => {
58	    if (!search.trim()) return cleanCategories;
59	    const q = search.toLowerCase().trim();
60	    return cleanCategories.filter((c) => c.toLowerCase().includes(q));
61	  }, [cleanCategories, search]);
62	
63	  const exactMatchExists = useMemo(() => {
64	    const q = search.toLowerCase().trim();
65	    if (!q) return true;
66	    return cleanCategories.some((c) => c.toLowerCase() === q);
67	  }, [cleanCategories, search]);
68	
69	  const handleSelect = (cat: string) => {
70	    onChange(cat);
71	    setIsOpen(false);
72	    setSearch('');
73	  };
74	
75	  const handleCreateNew = () => {
76	    const trimmed = search.trim();
77	    if (!trimmed) return;
78	    const formatted = trimmed.charAt(0).toUpperCase() + trimmed.slice(1);
79	    if (onAddNewCategory) onAddNewCategory(formatted);
80	    onChange(formatted);
81	    setIsOpen(false);
82	    setSearch('');
83	  };
84	
85	  return (
86	    <div className="relative inline-block w-full" ref={popoverRef}>
87	      {/* Trigger Button: Notion Style Pill */}
88	      <button
89	        type="button"
90	        onClick={(e) => {
91	          e.stopPropagation();
92	          setIsOpen(!isOpen);
93	        }}
94	        className={`inline-flex items-center justify-between gap-1.5 px-2.5 py-1 rounded-lg border text-xs font-mono font-bold transition-all w-full max-w-[150px] truncate ${getCategoryBadgeStyle(
95	          value || 'General'
96	        )} hover:brightness-110 active:scale-95`}
97	      >
98	        <span className="truncate">{value || 'General'}</span>
99	        <ChevronDown className="w-3 h-3 opacity-60 shrink-0" />
100	      </button>
101	
102	      {/* Notion Popover Dropdown */}
103	      {isOpen && (
104	        <div
105	          onClick={(e) => e.stopPropagation()}
106	          className="absolute left-0 top-full mt-1 z-50 w-60 rounded-2xl bg-hazard-card border-2 border-hazard-gold/60 shadow-2xl backdrop-blur-xl p-2 flex flex-col gap-1.5 animate-fadeIn"
107	        >
108	          {/* Search / Create Input */}
109	          <div className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl bg-hazard-void border border-hazard-border">
110	            <Search className="w-3.5 h-3.5 text-hazard-textMuted shrink-0" />
111	            <input
112	              ref={searchInputRef}
113	              type="text"
114	              placeholder="Search or type new..."
115	              value={search}
116	              onChange={(e) => setSearch(e.target.value)}
117	              onKeyDown={(e) => {
118	                if (e.key === 'Enter') {
119	                  e.preventDefault();
120	                  if (!exactMatchExists && search.trim()) {
121	                    handleCreateNew();
122	                  } else if (filteredCategories.length > 0) {
123	                    handleSelect(filteredCategories[0]);
124	                  }
125	                } else if (e.key === 'Escape') {
126	                  setIsOpen(false);
127	                }
128	              }}
129	              className="w-full bg-transparent text-xs font-mono text-hazard-textBright placeholder:text-hazard-textMuted/50 outline-none"
130	            />
131	          </div>
132	
133	          {/* Create New Category Option (if not exact match) */}
134	          {!exactMatchExists && search.trim() && (
135	            <button
136	              type="button"
137	              onClick={handleCreateNew}
138	              className="flex items-center gap-2 px-2.5 py-1.5 rounded-xl bg-hazard-cyan/15 hover:bg-hazard-cyan/25 text-hazard-cyan border border-hazard-cyan/40 text-xs font-mono font-bold transition text-left"
139	            >
140	              <Plus className="w-3.5 h-3.5" />
141	              <span>Create "{search.trim()}"</span>
142	            </button>
143	          )}
144	
145	          {/* Existing Categories List */}
146	          <div className="flex flex-col gap-0.5 max-h-48 overflow-y-auto pr-0.5 scrollbar-thin">
147	            <span className="text-[10px] font-mono text-hazard-textMuted px-2 py-0.5 uppercase tracking-wider">
148	              Select Category
149	            </span>
150	            {filteredCategories.map((cat) => {
151	              const isSelected = (value || 'General').toLowerCase() === cat.toLowerCase();
152	              return (
153	                <button
154	                  key={cat}
155	                  type="button"
156	                  onClick={() => handleSelect(cat)}
157	                  className={`flex items-center justify-between gap-2 px-2.5 py-1.5 rounded-xl text-xs font-mono transition text-left ${
158	                    isSelected
159	                      ? 'bg-hazard-gold/20 text-hazard-gold font-bold border border-hazard-gold/40'
160	                      : 'text-hazard-textMuted hover:text-white hover:bg-hazard-void'
161	                  }`}
162	                >
163	                  <span className={`px-2 py-0.5 rounded-md border text-[11px] font-bold ${getCategoryBadgeStyle(cat)}`}>
164	                    {cat}
165	                  </span>
166	                  {isSelected && <Check className="w-3.5 h-3.5 text-hazard-gold" />}
167	                </button>
168	              );
169	            })}
170	          </div>
171	        </div>
172	      )}
173	    </div>
174	  );
175	};
